select u.id, u.content_sha256, 'Aplicam-se as disposições da Lei de Organizações Criminosas para a investigação, processo e julgamento dos crimes previstos na Lei Antiterrorismo.', '["Aplica-se a Lei de Organizações Criminosas à investigação, ao processo e ao julgamento do terrorismo."]'::jsonb, '["Permite colaboração premiada, ação controlada, infiltração e outros meios de prova da lei de organizações criminosas."]'::jsonb, 'Na investigação de terrorismo, cabe a colaboração premiada da lei de organizações criminosas.', '["Assertiva que afasta a Lei de Organizações Criminosas da investigação do terrorismo erra."]'::jsonb, '[]'::jsonb, '["Art. 17"]'::jsonb, 'under_review', 'claude'
