insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aplicam-se as disposições da Lei dos Crimes Hediondos aos crimes previstos na Lei Antiterrorismo.', '["Aplica-se a Lei dos Crimes Hediondos ao terrorismo."]'::jsonb, '["Terrorismo é equiparado a hediondo."]'::jsonb, 'O terrorismo é insuscetível de anistia, graça, indulto e fiança.', '["Assertiva que considera o terrorismo crime comum, sem o tratamento dos hediondos, erra."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'terrorismo' and u.unit_key = 'art-17'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

